from collections import deque

def find_connected_components(grid):
    """Find connected components of non-background cells"""
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 8 and (r, c) not in visited:
                comp = {'color': grid[r][c], 'cells': [], 'bbox': {}}
                queue = deque([(r, c)])
                min_r, max_r, min_c, max_c = r, r, c, c

                while queue:
                    curr_r, curr_c = queue.popleft()
                    if (curr_r, curr_c) not in visited:
                        visited.add((curr_r, curr_c))
                        comp['cells'].append((curr_r, curr_c))
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if grid[nr][nc] != 8 and (nr, nc) not in visited:
                                    queue.append((nr, nc))

                comp['bbox'] = {
                    'min_r': min_r, 'max_r': max_r,
                    'min_c': min_c, 'max_c': max_c,
                    'height': max_r - min_r + 1,
                    'width': max_c - min_c + 1
                }
                components.append(comp)
    return components

